  int doPeek() throws IOException {
    int peekStack = stack[stackSize - 1];
    switch (peekStack) {
      case JsonScope.EMPTY_ARRAY:
        stack[stackSize - 1] = JsonScope.NONEMPTY_ARRAY;
        break;
      case JsonScope.NONEMPTY_ARRAY:
        {
          // Look for a comma before the next element.
          int c = nextNonWhitespace(true);
          switch (c) {
            case ']':
              peeked = PEEKED_END_ARRAY;
              return peeked;
            case ';':
              checkLenient(); // fall-through
            case ',':
              break;
            default:
              throw syntaxError("Unterminated array");
          }
          break;
        }
      case JsonScope.EMPTY_OBJECT:
      case JsonScope.NONEMPTY_OBJECT:
        {
          stack[stackSize - 1] = JsonScope.DANGLING_NAME;
          // Look for a comma before the next element.
          if (peekStack == JsonScope.NONEMPTY_OBJECT) {
            int c = nextNonWhitespace(true);
            switch (c) {
              case '}':
                peeked = PEEKED_END_OBJECT;
                return peeked;
              case ';':
                checkLenient(); // fall-through
              case ',':
                break;
              default:
                throw syntaxError("Unterminated object");
            }
          }
          int c = nextNonWhitespace(true);
          switch (c) {
            case '"':
              peeked = PEEKED_DOUBLE_QUOTED_NAME;
              return peeked;
            case '\'':
              checkLenient();
              peeked = PEEKED_SINGLE_QUOTED_NAME;
              return peeked;
            case '}':
              if (peekStack != JsonScope.NONEMPTY_OBJECT) {
                peeked = PEEKED_END_OBJECT;
                return peeked;
              } else {
                throw syntaxError("Expected name");
              }
            default:
              checkLenient();
              pos--; // Don't consume the first character in an unquoted string.
              if (isLiteral((char) c)) {
                peeked = PEEKED_UNQUOTED_NAME;
                return peeked;
              } else {
                throw syntaxError("Expected name");
              }
          }
        }
      case JsonScope.DANGLING_NAME:
        {
          stack[stackSize - 1] = JsonScope.NONEMPTY_OBJECT;
          // Look for a colon before the value.
          int c = nextNonWhitespace(true);
          switch (c) {
            case ':':
              break;
            case '=':
              checkLenient();
              if ((pos < limit || fillBuffer(1)) && buffer[pos] == '>') {
                pos++;
              }
              break;
            default:
              throw syntaxError("Expected ':'");
          }
          break;
        }
      case JsonScope.EMPTY_DOCUMENT:
        if (strictness == Strictness.LENIENT) {
          consumeNonExecutePrefix();
        }
        stack[stackSize - 1] = JsonScope.NONEMPTY_DOCUMENT;
        break;
      case JsonScope.NONEMPTY_DOCUMENT:
        {
          int c = nextNonWhitespace(false);
          if (c == -1) {
            peeked = PEEKED_EOF;
            return peeked;
          } else {
            checkLenient();
            pos--;
          }
          break;
        }
      case JsonScope.CLOSED:
        throw new IllegalStateException("JsonReader is closed");
      default:
        throw new AssertionError(peekStack);
    }

    int c = nextNonWhitespace(true);
    switch (c) {
      case ']':
        if (peekStack == JsonScope.EMPTY_ARRAY) {
          peeked = PEEKED_END_ARRAY;
          return peeked;
        }
      // fall-through to handle ",]"
      case ';':
      case ',':
        // In lenient mode, a 0-length literal in an array means 'null'.
        if (peekStack == JsonScope.EMPTY_ARRAY || peekStack == JsonScope.NONEMPTY_ARRAY) {
          checkLenient();
          pos--;
          peeked = PEEKED_NULL;
          return peeked;
        } else {
          throw syntaxError("Unexpected value");
        }
      case '\'':
        checkLenient();
        peeked = PEEKED_SINGLE_QUOTED;
        return peeked;
      case '"':
        peeked = PEEKED_DOUBLE_QUOTED;
        return peeked;
      case '[':
        peeked = PEEKED_BEGIN_ARRAY;
        return peeked;
      case '{':
        peeked = PEEKED_BEGIN_OBJECT;
        return peeked;
      default:
        pos--; // Don't consume the first character in a literal value.
    }

    int result = peekKeyword();
    if (result != PEEKED_NONE) {
      return result;
    }

    result = peekNumber();
    if (result != PEEKED_NONE) {
      return result;
    }

    if (!isLiteral(buffer[pos])) {
      throw syntaxError("Expected value");
    }

    checkLenient();
    peeked = PEEKED_UNQUOTED;
    return peeked;
  }

